const assert = require('node:assert/strict');
const view = require('./review-metrics.js');
const row = (row, merchant, direction, cents, platform='微信', time='2026-09-01 10:00:00') => ({row,merchant,direction,cents,platform,time});
const rows = [row(1,'单位甲','收入',500), row(2,'单位甲','收入',300,'支付宝'),
  row(3,'商户','支出',200), row(4,'商户','中性交易',999), row(5,'单位甲','收入',100,'微信','2026-08-01 10:00:00')];
const analysis = {salary:{rows:[1,2,5]},large:{rows:[1,3]},night:{rows:[3]}};
const months = [{month:'2026-08'},{month:'2026-09'}];
const snapshot = JSON.stringify(rows);
const v = view(rows,analysis,months,{start:'2026-09-01',end:'2026-09-30',platform:'微信'});
assert.equal(v.salary?.income,500,'salary must respect platform and date filters');
assert.deepEqual(v.salary.rows.map(r=>r.row),[1]);
assert.deepEqual(v.large.rows.map(r=>r.row),[1,3]);
assert.deepEqual(v.night.rows.map(r=>r.row),[3]);
assert.equal(v.incoming.total,500);
assert.equal(v.outgoing.total,200,'neutral records must not enter flow amounts');
assert.equal(v.salary.monthly.length,1);
assert.equal(JSON.stringify(rows),snapshot,'view calculation must not mutate source records');
const all=view(rows,analysis,months,{start:'2026-08-01',end:'2026-09-30',platform:''});
assert.equal(all.salary.sources.length,2,'same merchant on two platforms stays separate');
assert.deepEqual(all.salary.monthly.map(m=>m.income),[100,800]);
const empty=view(rows,analysis,months,{start:'2026-10-01',end:'2026-09-30',platform:''});
assert.equal(empty.salary.income,0);
assert.equal(empty.incoming.total,0);
assert.deepEqual(empty.salary.monthly,[]);
const many=Array.from({length:8},(_,i)=>row(i+1,'对方'+i,'收入',(i+1)*100));
const top=view(many,{salary:{rows:[]},large:{rows:[]},night:{rows:[]}},months,{start:'2026-09-01',end:'2026-09-30',platform:''});
assert.equal(top.incoming.nodes.length,6,'five counterparties plus a residual group');
assert.equal(top.incoming.nodes[5].cents,600);
assert.equal(top.incoming.nodes.reduce((s,n)=>s+n.cents,0),3600);
assert.equal(new Set(top.incoming.nodes.flatMap(n=>n.rows.map(r=>r.row))).size,8);
console.log('PASS: filtered salary, boundary/empty views, platform separation, flow residual and immutable source data');
